select *,CAST(REPLACE(age_grade, '%', '') AS REAL) AS age_grade_numeric, round(CAST(REPLACE(age_grade, '%', '') AS REAL)*CAST(time_seconds AS REAL)/50,0) as age_calc
from eventpositions_view
where age_group='MWC' 
 --and age_calc>1580
order by age_calc,athlete_code

select age_group,round(CAST(REPLACE(age_grade, '%', '') AS REAL)*CAST(time_seconds AS REAL)/50,0) as age_calc,count(*)
from eventpositions_view
where age_calc>0
group by age_group,age_calc

select *,CAST(REPLACE(age_grade, '%', '') AS REAL) AS age_grade_numeric, round(CAST(REPLACE(age_grade, '%', '') AS REAL)*CAST(time_seconds AS REAL)/50,0) as age_calc
 from  eventpositions_view where athlete_code='4598782' and formatted_date between '2011-01-01' and '2025-08-30' order by formatted_date 

 
 select * from age_category
 
 SELECT 
    epv.*,
    CAST(REPLACE(epv.age_grade, '%', '') AS REAL) AS age_grade_numeric,
    ROUND(CAST(REPLACE(epv.age_grade, '%', '') AS REAL) * CAST(epv.time_seconds AS REAL) / 50, 0) AS age_calc,
    ac.age,
    ac.sex,
    ac.lower_bound,
    ac.upper_bound,
    ac.male_age_ratio,
    ac.sex_age_ratio
	FROM eventpositions_view epv
JOIN age_category ac
  ON epv.age_group = ac.age_group
 AND ROUND(CAST(REPLACE(epv.age_grade, '%', '') AS REAL) * CAST(epv.time_seconds AS REAL) / 50, 0) BETWEEN ac.lower_bound AND ac.upper_bound
WHERE epv.athlete_code = '4839496'
  --AND epv.formatted_date BETWEEN '2011-01-01' AND '2025-08-30'
ORDER BY epv.formatted_date
	
Select     epv.formatted_date,name,epv.age_group,athlete_code,age
FROM eventpositions_view epv
JOIN age_category ac
  ON epv.age_group = ac.age_group
 AND ROUND(CAST(REPLACE(epv.age_grade, '%', '') AS REAL) * CAST(epv.time_seconds AS REAL) / 50, 0) BETWEEN ac.lower_bound AND ac.upper_bound
WHERE epv.athlete_code = '4839496'
 -- AND epv.formatted_date BETWEEN '2011-01-01' AND '2025-08-30'
ORDER BY epv.formatted_date

WITH age_changes AS (
  SELECT
    *,
    LAG(age) OVER (ORDER BY formatted_date) AS prev_age,
    LAG(formatted_date) OVER (ORDER BY formatted_date) AS prev_date,
	LAG(age_group) OVER (ORDER BY formatted_date) AS prev_age_group
  FROM (
    -- Your joined query here
    SELECT
      epv.formatted_date,
      epv.name,
      epv.age_group,
      epv.athlete_code,
      age
    FROM eventpositions_view epv
    JOIN age_category ac
      ON epv.age_group = ac.age_group
     AND ROUND(CAST(REPLACE(epv.age_grade, '%', '') AS REAL) * CAST(epv.time_seconds AS REAL) / 50, 0) BETWEEN ac.lower_bound AND ac.upper_bound
    WHERE epv.athlete_code = '4839496'
   --   AND epv.formatted_date BETWEEN '2011-01-01' AND '2025-08-30'
    ORDER BY epv.formatted_date
  )
)
SELECT
  prev_date AS min_date,
  formatted_date AS max_date,
  prev_age AS age_before,
  age AS age_after,
  prev_age_group As age_group_before,
  age_group as age_group_after,
  -- Fix: Subtract (prev_age - 1) years for latest_possible_dob
  DATE(prev_date, '+1 day', '-' || (prev_age + 1) || ' years') AS latest_possible_dob,
  DATE(formatted_date, '-' || age || ' years') AS earliest_possible_dob
FROM age_changes
WHERE prev_age IS NOT NULL -- AND age > prev_age
ORDER BY formatted_date



WITH athlete_ages AS (
  SELECT
    epv.athlete_code,
    epv.formatted_date,
    ac.age_group,
    ac.age,
    -- Calculate age_calc as before
    ROUND(CAST(REPLACE(epv.age_grade, '%', '') AS REAL) * CAST(epv.time_seconds AS REAL) / 50, 0) AS age_calc
  FROM eventpositions_view epv
  JOIN age_category ac
    ON epv.age_group = ac.age_group
   AND ROUND(CAST(REPLACE(epv.age_grade, '%', '') AS REAL) * CAST(epv.time_seconds AS REAL) / 50, 0)
       BETWEEN ac.lower_bound AND ac.upper_bound
),
age_changes AS (
  SELECT
    athlete_code,
    formatted_date,
    age,
    LAG(age) OVER (PARTITION BY athlete_code ORDER BY formatted_date) AS prev_age,
    LAG(formatted_date) OVER (PARTITION BY athlete_code ORDER BY formatted_date) AS prev_date
  FROM athlete_ages
),
dob_ranges AS (
  SELECT
    athlete_code,
    prev_date,
    formatted_date,
    prev_age,
    age,
    DATE(prev_date, '+1 day', '-' || (prev_age + 1) || ' years') AS latest_possible_dob,
    DATE(formatted_date, '-' || age || ' years') AS earliest_possible_dob
  FROM age_changes
  WHERE prev_age IS NOT NULL -- AND age > prev_age
)
SELECT
  athlete_code,
  MAX(latest_possible_dob) AS latest_possible_dob,
  MIN(earliest_possible_dob) AS earliest_possible_dob
FROM dob_ranges
GROUP BY athlete_code
ORDER BY athlete_code;


