 drop table age_category
 
 CREATE TABLE age_category (
    age INTEGER,
	sex TEXT,
    age_group TEXT,
    lower_bound INTEGER,
    target_bound INTEGER,
    upper_bound INTEGER,
    male_age_ratio REAL,
    sex_age_ratio REAL
);

ALTER TABLE age_category ADD COLUMN age_max INTEGER;

DELETE FROM age_category
WHERE sex = 'F' AND age IN (29);

UPDATE age_category
SET age_max = age;

UPDATE age_category
SET age_group = 'SW20-24'
WHERE age = 22 AND sex = 'F';

UPDATE age_category
SET lower_bound = 0,target_bound=1548,upper_bound=2776
WHERE age = 25 AND sex = 'M';

UPDATE age_category
set age_max=29
where age=25 and sex='F'

select * from age_category order by sex DESC,age



CREATE TABLE athletes AS
SELECT athlete_code, name, club, NULL AS dob
FROM (
    SELECT
        athlete_code,
        name,
        club,
        ROW_NUMBER() OVER (
            PARTITION BY athlete_code
            ORDER BY DATE(formatted_date) DESC
        ) AS rn
    FROM eventpositions_view
)
WHERE rn = 1;

select * from athletes order by club

